import json
with open('baseline-packages.json') as f: b=json.load(f)
with open('/tmp/after-cpm-good.json') as f: a=json.load(f)
for bp, ap in zip(b['projects'], a['projects']):
    for bf, af in zip(bp['frameworks'], ap['frameworks']):
        for bpkg, apkg in zip(bf['topLevelPackages'], af['topLevelPackages']):
            if bpkg != apkg:
                print(f'DIFF: {bpkg} vs {apkg}')
print('Package versions are identical' if all(
    bpkg == apkg
    for bp, ap in zip(b['projects'], a['projects'])
    for bf, af in zip(bp['frameworks'], ap['frameworks'])
    for bpkg, apkg in zip(bf['topLevelPackages'], af['topLevelPackages'])
) else 'DIFFERENCES FOUND')
"

